#include "BluetoothA2DPSink.h"
#include <Wire.h>
#include <LiquidCrystal_I2C.h>
#include "AiEsp32RotaryEncoder.h" 

// --- НАСТРОЙКА ПИНОВ ---
// I2S для ЦАП PCM5102A
#define I2S_BCK      26
#define I2S_WS       25
#define I2S_DOUT     33 // Перенесли сюда, чтобы освободить пин 22 для I2C 

// I2C для LCD 1602
#define I2C_SDA      21
#define I2C_SCL      22 

// Энкодер
#define ROTARY_ENCODER_CLK_PIN 14
#define ROTARY_ENCODER_DT_PIN  12
#define ROTARY_ENCODER_SW_PIN  13
#define ROTARY_ENCODER_VCC_PIN -1
#define ROTARY_ENCODER_STEPS   4 

// --- ИНИЦИАЛИЗАЦИЯ ОБЪЕКТОВ ---
BluetoothA2DPSink a2dp_sink;
LiquidCrystal_I2C lcd(0x27, 16, 2); // Проверьте адрес I2C (0x27 или 0x3F)
AiEsp32RotaryEncoder rotaryEncoder = AiEsp32RotaryEncoder(ROTARY_ENCODER_CLK_PIN, ROTARY_ENCODER_DT_PIN, ROTARY_ENCODER_SW_PIN, ROTARY_ENCODER_VCC_PIN, ROTARY_ENCODER_STEPS); 

// Переменные для состояния
String current_title = "";
String current_artist = "";
bool need_update_display = true;
unsigned long last_button_press = 0; 

// Простая функция транслитерации для корректного отображения на стандартном LCD 1602
String transliterate(String text) {
String result = "";
struct Convert { const char* rus; const char* eng; };
// Базовый набор для экономии памяти, можно расширить
static const Convert table[] = {
{"а","a"},{"б","b"},{"в","v"},{"г","g"},{"д","d"},{"е","e"},{"ё","yo"},{"ж","zh"},{"з","z"},{"и","i"},{"й","y"},
{"к","k"},{"л","l"},{"м","m"},{"н","n"},{"о","o"},{"п","p"},{"р","r"},{"с","s"},{"т","t"},{"у","u"},{"ф","f"},
{"х","kh"},{"ц","ts"},{"ч","ch"},{"ш","sh"},{"щ","shch"},{"ъ",""},{"ы","y"},{"ь",""},{"э","e"},{"ю","yu"},{"я","ya"},
{"А","A"},{"Б","B"},{"В","V"},{"Г","G"},{"Д","D"},{"Е","E"},{"Ё","Yo"},{"Ж","Zh"},{"З","Z"},{"И","I"},{"Й","Y"},
{"К","K"},{"Л","L"},{"М","M"},{"Н","N"},{"О","O"},{"П","P"},{"Р","R"},{"С","S"},{"Т","T"},{"У","U"},{"Ф","F"},
{"Х","Kh"},{"Ц","Ts"},{"Ч","Ch"},{"Ш","Sh"},{"Щ","Shch"},{"Э","E"},{"Ю","Yu"},{"Я","Ya"}
}; 

for (int i = 0; i < text.length(); i++) {
bool found = false;
// Проверяем UTF-8 символы (они занимают 2 байта)
if ((uint8_t)text[i] == 0xD0 || (uint8_t)text[i] == 0xD1) {
String utfChar = text.substring(i, i + 2);
for (const auto& item : table) {
if (utfChar == item.rus) {
result += item.eng;
found = true;
break;
}
}
i++; // Пропускаем второй байт UTF-8
} else {
// Обычный ASCII
result += text[i];
found = true;
}
if (!found) result += "?";
}
return result;
} 

// Обработчик изменения громкости с энкодера
void rotary_loop() {
if (rotaryEncoder.encoderChanged()) {
int volume = rotaryEncoder.readEncoder();
a2dp_sink.set_volume(volume); 

lcd.setCursor(0, 1);
lcd.print("Vol: ");
lcd.print(volume);
lcd.print("%   ");
delay(500); // Кратковременно показываем громкость, затем сбросим флаг на обновление
need_update_display = true;
} 

// Обработка кнопки энкодера (короткое нажатие — пауза, длинное — следующий трек)
if (rotaryEncoder.isEncoderButtonClicked()) {
unsigned long play_back_milli = millis();
if (play_back_milli - last_button_press > 300) { // защиту от дребезга
if (a2dp_sink.get_audio_state() == ESP_A2D_AUDIO_STATE_STARTED) {
a2dp_sink.pause();
lcd.setCursor(0, 1);
lcd.print("Paused          ");
} else {
a2dp_sink.play();
need_update_display = true;
}
last_button_press = play_back_milli;
}
}
} 

void read_encoder_ISR() {
rotaryEncoder.readEncoder_ISR();
} 

// Колбэк-функция для получения метаданных от смартфона
void avrc_metadata_callback(uint8_t id, const uint8_t *text) {
String value = String((char*)text);
value = transliterate(value); 

if (id == ESP_AVRC_MD_ATTR_TITLE) {
current_title = value;
} else if (id == ESP_AVRC_MD_ATTR_ARTIST) {
current_artist = value;
}
need_update_display = true;
} 

void update_display() {
if (!need_update_display) return;
need_update_display = false; 

lcd.clear(); 

// Строка 1: Название трека
if (current_title.length() > 0) {
lcd.setCursor(0, 0);
lcd.print(current_title.substring(0, 16)); // Обрезаем под размер экрана
} else {
lcd.setCursor(0, 0);
lcd.print("Bluetooth Audio");
} 

// Строка 2: Исполнитель
lcd.setCursor(0, 1);
if (current_artist.length() > 0) {
lcd.print(current_artist.substring(0, 16));
} else {
lcd.print("Ready to pair...");
}
} 

void setup() {
// Настройка I2C на выбранные пины
Wire.begin(I2C_SDA, I2C_SCL); 

// Инициализация дисплея
lcd.init();
lcd.backlight();
lcd.setCursor(0, 0);
lcd.print("Booting..."); 

// Инициализация энкодера
rotaryEncoder.begin();
rotaryEncoder.setup(read_encoder_ISR);
rotaryEncoder.setBoundaries(0, 100, false); // Громкость от 0 до 100
rotaryEncoder.setAcceleration(250);
rotaryEncoder.setEncoderValue(70); // Стартовая громкость 70% 

// Конфигурация I2S выводов для PCM5102A
i2s_pin_config_t my_pin_config = {
.bck_io_num = I2S_BCK,
.ws_io_num = I2S_WS,
.data_out_num = I2S_DOUT,
.data_in_num = I2S_PIN_NO_CHANGE
};
a2dp_sink.set_pin_config(my_pin_config); 

// Настройка Bluetooth и колбэков
a2dp_sink.set_avrc_metadata_callback(avrc_metadata_callback);
a2dp_sink.set_volume(70); 

// Запуск Bluetooth-сервера (имя устройства при поиске)
a2dp_sink.start("ESP32_HiFi_Sound"); 

lcd.clear();
lcd.print("BT Sink Ready");
} 

void loop() {
rotary_loop();
update_display();
delay(10);
}
